#ifndef CMATRIX_H
#define CMATRIX_H

/* Matrix configuration */
#define MATRIX_WIDTH 80
#define MATRIX_HEIGHT 24
#define MAX_CHARS 256

/* Character sets */
extern const char *latin_chars;
extern const char *katakana_chars;
extern const char *lambda_chars;

/* Matrix state */
typedef struct {
    char **grid;
    int width;
    int height;
    int color;
    int bold;
    int async;
    int old_style;
    int char_change;
    int use_japanese;
    int lambda_mode;
    int rainbow;
    int all_bold;
    int no_bold;
} matrix_t;

/* Initialize the matrix */
void init_matrix(void);

/* Run the matrix simulation */
void run_matrix(void);

/* Cleanup resources */
void cleanup(void);
```

