    if (matrix.grid) {
        for (i = 0; i < matrix.height; i++) {
            free(matrix.grid[i]);
        }
        free(matrix.grid);
    }

    if (tty_fd >= 0 && tty_fd != STDOUT_FILENO) {
        close(tty_fd);
    }
}

