            matrix.async = !matrix.async;
        } else if (c == 'b' || c == 'B') {
            matrix.bold = !matrix.bold;
        } else if (c == 'n' || c == 'N') {
            matrix.bold = 0;
            matrix.all_bold = 0;
        } else if (c >= '0' && c <= '9') {
            update_delay = c - '0';
