            matrix.color = 1;  /* red */
        } else if (c == '@') {
            matrix.color = 0;  /* green */
        } else if (c == '#') {
            matrix.color = 4;  /* yellow */
        } else if (c == '$') {
            matrix.color = 2;  /* blue */
        } else if (c == '%') {
            matrix.color = 6;  /* magenta */
        } else if (c == '^') {
            matrix.color = 5;  /* cyan */
        } else if (c == '&') {
            matrix.color = 3;  /* white */
        } else if (c == ')') {
            matrix.color = 7;  /* black */
