+++/* Set terminal color */
+++void set_color(void) {
+++    int color_code;
+++    
+++    switch (matrix.color) {
+++        case 0: /* green */
+++            color_code = 32;
+++            break;
+++        case 1: /* red */
+++            color_code = 31;
+++            break;
+++        case 2: /* blue */
+++            color_code = 34;
+++            break;
+++        case 3: /* white */
+++            color_code = 37;
+++            break;
+++        case 4: /* yellow */
+++            color_code = 33;
+++            break;
+++        case 5: /* cyan */
+++            color_code = 36;
+++            break;
+++        case 6: /* magenta */
+++            color_code = 35;
+++            break;
+++        case 7: /* black */
+++            color_code = 30;
+++            break;
+++        default:
+++            color_code = 32;
+++            break;
