+++/* Handle keyboard input */
+++void handle_input(const char *buf) {
+++    int i;
+++    
+++    for (i = 0; buf[i] != '\0'; i++) {
+++        char c = buf[i];
+++        
+++        if (c == 'q' || c == 'Q') {
+++            running = 0;
+++            break;
+++        } else if (c == 'a' || c == 'A') {
+++            matrix.async = !matrix.async;
+++        } else if (c == 'b' || c == 'B') {
+++            matrix.bold = !matrix.bold;
+++        } else if (c == 'n' || c == 'N') {
+++            matrix.bold = 0;
+++            matrix.all_bold = 0;
+++        } else if (c >= '0' && c <= '9') {
+++            update_delay = c - '0';
+++        } else if (c == '!') {
+++            matrix.color = 0;
+++        } else if (c == '@') {
+++            matrix.color = 0;
+++        } else if (c == '#') {
+++            matrix.color = 2;
+++        } else if (c == '$') {
+++            matrix.color = 3;
+++        } else if (c == '%') {
+++            matrix.color = 4;
+++        } else if (c == '^') {
+++            matrix.color = 5;
+++        } else if (c == '&') {
+++            matrix.color = 6;
+++        } else if (c == ')') {
+++            matrix.color = 7;
+++        }
+++    }
+++}
