++            matrix.all_bold = 0;
++        } else if (c >= '0' && c <= '9') {
++            update_delay = c - '0';
++        } else if (c == '!') {
++            matrix.color = 0;
++        } else if (c == '@') {
++            matrix.color = 0;
++        } else if (c == '#') {
++            matrix.color = 2;
++        } else if (c == '$') {
++            matrix.color = 3;
++        } else if (c == '%') {
++            matrix.color = 4;
++        } else if (c == '^') {
