+    printf("All bold characters (overrides \\-b)\n");
+    printf(".TP\n");
+    printf(".I \"\\-f\"\n");
+    printf("Force the linux $TERM type to be on\n");
+    printf(".TP\n");
+    printf(".I \"\\-l\"\n");
+    printf("Linux mode (sets \"matrix.fnt\" font in console)\n");
+    printf(".TP\n");
+    printf(".I \"\\-o\"\n");
+    printf("Use old-style scrolling\n");
+    printf(".TP\n");
+    printf(".I \"\\-c\"\n");
+    printf("Only print the shadows of letters \n");
+    printf(".TP\n");
+    printf(".I \"\\-L\"\n");
+    printf("Locks cmatrix, Unable to quit\n");
+    printf(".TP\n");
+    printf(".I \"\\-h, \\-?\"\n");
+    printf("Print usage and exit\n");
+    printf(".TP\n");
+    printf(".I \"\\-r\"\n");
+    printf("\"Rainbow\" mode, rainbow colored character\n");
+    printf(".TP\n");
+    printf(".I \"\\-k\"\n");
+    printf("Every characters change \n");
+    printf(".TP\n");
+    printf(".I \"\\-n\"\n");
+    printf("No bold characters (overrides \\-b and \\-B, default)\n");
+    printf(".TP\n");
+    printf(".I \"\\-s\"\n");
+    printf("\"Screensaver\" mode, exits on first keystroke\n");
+    printf(".TP\n");
+    printf(".I \"\\-m\"\n");
+    printf("Lambda mode, every character becomes a lambda\n");
+    printf(".TP\n");
+    printf(".I \"\\-x\"\n");
+    printf("X window mode, use if your xterm is using mtx.pcf\n");
+    printf(".TP\n");
+    printf(".I \"\\-V\"\n");
+    printf("Print version information and exit\n");
+    printf(".TP\n");
+    printf(".I \"\\-u delay\"\n");
+    printf("Screen update delay 0 - 9, default 4\n");
+    printf(".TP\n");
+    printf(".I \"\\-C color\"\n");
+    printf("Use this color for matrix (default green).\n");
+    printf("Valid colors are green, red, blue, white, yellow, cyan, magenta and black.\n");
