+/* Get color string */
+const char *get_color_string(void) {
+    switch (matrix.color) {
+        case 0: return "green";
+        case 1: return "red";
+        case 2: return "blue";
+        case 3: return "white";
+        case 4: return "yellow";
+        case 5: return "cyan";
+        case 6: return "magenta";
+        case 7: return "black";
+        default: return "green";
+    }
+}
